@Component({ standalone: true })
export class PlanningBoard {
  readonly density = signal<Density>('comfortable');
  readonly selectedId = signal<string | null>(null);

  // Derived state stays derived — no second source of truth.
  readonly rowHeight = computed(() => DENSITY[this.density()]);
  readonly selected = computed(() =>
    this.plans().find((p) => p.id === this.selectedId()) ?? null,
  );
}

@Injectable({ providedIn: 'root' })
export class PlanStore {
  private readonly entities = signal<PlanEntities>(EMPTY);
  private readonly intents = inject(PlanEventStream).intents$;

  readonly plans = computed(() => this.entities().plans);

  constructor() {
    // Idempotent reduction means replays and reconnects converge.
    this.intents.pipe(
      takeUntilDestroyed(),
      scan(this.reduce, this.entities()),
    ).subscribe((next) => this.entities.set(next));
  }

  private reduce = (state: PlanEntities, intent: PlanIntent): PlanEntities =>
    PlanReducer.apply(state, intent);
}
